class Solution {
public:
    int findMinFibonacciNumbers(int k) {
        long long a = 1, b = 1;
        while (b <= k) {
            long long c = a + b;
            a = b;
            b = c;
        }
        // a = largest Fibonacci <= k, b = next Fibonacci > k
        int count = 0;
        long long kk = k;
        while (kk > 0) {
            while (a > kk) {
                long long temp = a;
                a = b - a;   // F_{n-2} = F_n - F_{n-1}
                b = temp;    // old F_{n-1} becomes new successor
            }
            kk -= a;
            count++;
        }
        return count;
    }
};
